effect.shader:
precision highp float;

#define PI 3.14159265359

mat3 rotX(float a) { float s = sin(a); float c = cos(a); return mat3(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c); }
mat3 rotY(float a) { float s = sin(a); float c = cos(a); return mat3(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c); }
mat3 rotZ(float a) { float s = sin(a); float c = cos(a); return mat3(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0); }

void main() {
    vec2 uv = acLayerNorm - 0.5;
    uv *= scale;

    float rx = (SPLITXYZ ? ROT2 : 0.0) * PI / 180.0;
    float ry = (SPLITXYZ ? ROT3 : 0.0) * PI / 180.0;
    float rz = (SPLITXYZ ? ROT4 : 0.0) * PI / 180.0;
    mat3 camMatrix = rotZ(rz) * rotY(ry) * rotX(rx);

    vec3 p3d = vec3(uv, 0.0);
    p3d = camMatrix * p3d;

    float persp = 1.0 / (p3d.z + fFOV);
    vec2 projUV = p3d.xy * persp + 0.5;

    vec4 col = vec4(0.0);

    // Avoid logical AND operators to prevent XML entity parsing bugs in KXmlParser
    float validX = step(0.0, projUV.x) * step(projUV.x, 1.0);
    float validY = step(0.0, projUV.y) * step(projUV.y, 1.0);
    float valid = validX * validY;

    if (valid > 0.5) {
        col = texture2D(inputImg.texture, projUV);
    }

    gl_FragColor = col;
}
